/**
 * @name Path traversal in file operations
 * @description User-controlled data flows to file system operations without proper sanitization
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Remote flow sources (HTTP request data)
    source instanceof RemoteFlowSource
    or
    // Request path/query parameters
    exists(DataFlow::AttrRead attr |
      attr.getAttributeName() in ["path", "query", "match_info", "rel_url"] and
      source = attr
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File system access operations
    sink = any(FileSystemAccess fa).getAPathArgument()
    or
    // Path operations that could lead to file access
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      sink = call.getArg(0)
    )
    or
    // Open file operations
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled input"

/**
 * @name Command injection in aiohttp
 * @description Detects command injection vulnerabilities where user input flows to command execution
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;

import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Server-Side Request Forgery (SSRF) in aiohttp
 * @description User-controlled URLs in HTTP requests can lead to SSRF
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-ssrf
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // aiohttp client request methods
      call = API::moduleImport("aiohttp").getMember(["ClientSession", "request", "get", "post", "put", "delete", "patch", "head", "options"]).getACall() and
      sink = call.getArg(0)
      or
      // ClientSession methods
      call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["request", "get", "post", "put", "delete", "patch", "head", "options"] and
      sink = call.getArg(0)
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;

import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF vulnerability: URL from $@.", source.getNode(), "user input"

